import { useState } from "react";
import apiAxios from "../config/axiosConfig";



const Secret = async () => {
        const [msg, setMsg] = useState("")

        try {
                const response = await apiAxios.get("/secured-route")
                if (response.status == 200) {
                        setMsg("HELLO")
                }
        } catch (error) {
                console.log(error)
        }
        

        return ( 
                <p>{msg}</p>
         );
}
 
export default Secret;
